PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA synchronous=FULL;
PRAGMA secure_delete=ON;
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admins(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS config_revisions(revision INTEGER PRIMARY KEY, config_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS config_drafts(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES admins(id), base_revision INTEGER NOT NULL, config_json TEXT NOT NULL, created_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'draft',validation_json TEXT,last_check_id TEXT,applied_operation_id TEXT);
CREATE TABLE IF NOT EXISTS config_operations(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES admins(id),kind TEXT NOT NULL,status TEXT NOT NULL,draft_id TEXT, draft_revision INTEGER,config_json TEXT,result_json TEXT,error TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS config_operation_owner ON config_operations(owner_id,created_at);
CREATE TABLE IF NOT EXISTS personality_versions(revision INTEGER PRIMARY KEY, personality_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS secrets(id TEXT PRIMARY KEY, kind TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, source_key TEXT UNIQUE, title TEXT NOT NULL, context_epoch INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), owner_id TEXT NOT NULL, client_message_id TEXT NOT NULL, input TEXT NOT NULL, config_json TEXT NOT NULL, context_epoch INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed','cancelled','interrupted')), response TEXT, error TEXT, skill_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(conversation_id,client_message_id));
CREATE INDEX IF NOT EXISTS runs_queue ON runs(status,created_at);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), run_id TEXT NOT NULL REFERENCES runs(id), role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(run_id,role));
CREATE TABLE IF NOT EXISTS records(id TEXT PRIMARY KEY, kind TEXT NOT NULL, owner_id TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('private','shared')), revision INTEGER NOT NULL, payload TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER);
CREATE INDEX IF NOT EXISTS record_scope ON records(kind,owner_id,visibility,deleted_at,updated_at);
CREATE VIRTUAL TABLE IF NOT EXISTS record_fts USING fts5(content, tokenize='trigram');
CREATE TRIGGER IF NOT EXISTS record_insert AFTER INSERT ON records WHEN new.deleted_at IS NULL BEGIN INSERT INTO record_fts(rowid,content) VALUES(new.rowid,new.payload); END;
CREATE TRIGGER IF NOT EXISTS record_update AFTER UPDATE ON records BEGIN DELETE FROM record_fts WHERE rowid=old.rowid; INSERT INTO record_fts(rowid,content) SELECT new.rowid,new.payload WHERE new.deleted_at IS NULL; END;
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT, owner_id TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, title TEXT NOT NULL, resource_id TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS audit_owner ON audit_events(owner_id,id);
CREATE TABLE IF NOT EXISTS channel_inbox(event_key TEXT PRIMARY KEY, channel TEXT NOT NULL, received_at INTEGER NOT NULL, run_id TEXT);
CREATE TABLE IF NOT EXISTS channel_outbox(id TEXT PRIMARY KEY, run_id TEXT NOT NULL UNIQUE REFERENCES runs(id), channel TEXT NOT NULL, target_json TEXT NOT NULL, credential_ref TEXT NOT NULL, content TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','sending','sent','failed','unknown','cancelled')), error TEXT, platform_message_id TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS channel_events(id TEXT PRIMARY KEY,channel TEXT NOT NULL,account_id TEXT NOT NULL,event_key TEXT NOT NULL UNIQUE,source_key TEXT NOT NULL,owner_id TEXT NOT NULL,payload_json TEXT,credential_ref TEXT NOT NULL,status TEXT NOT NULL,run_id TEXT,received_at INTEGER NOT NULL,ready_at INTEGER NOT NULL,deadline INTEGER NOT NULL,error TEXT);
CREATE INDEX IF NOT EXISTS channel_events_pending ON channel_events(status,ready_at);
CREATE TABLE IF NOT EXISTS run_targets(run_id TEXT PRIMARY KEY REFERENCES runs(id),channel TEXT NOT NULL,target_json TEXT NOT NULL,credential_ref TEXT NOT NULL,deadline INTEGER NOT NULL,account_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS delivery_parts(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES runs(id),sequence INTEGER NOT NULL,kind TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL,platform_id TEXT,error TEXT,not_before INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(run_id,sequence));
CREATE TABLE IF NOT EXISTS channel_state(channel TEXT PRIMARY KEY,revision INTEGER NOT NULL,generation TEXT NOT NULL,value_json TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_jobs(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,channel TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL,account_revision INTEGER NOT NULL,secret_json TEXT,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL,error TEXT);
CREATE TABLE IF NOT EXISTS source_grants(source_key TEXT PRIMARY KEY,revision INTEGER NOT NULL,capture INTEGER NOT NULL DEFAULT 0,allow_model INTEGER NOT NULL DEFAULT 0,can_sleep INTEGER NOT NULL DEFAULT 0,can_wake INTEGER NOT NULL DEFAULT 0,expires_at INTEGER,enabled_after INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS model_jobs(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,input_json TEXT,output_json TEXT,source_json TEXT NOT NULL,config_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,error TEXT,idempotency_key TEXT,UNIQUE(owner_id,idempotency_key));
CREATE INDEX IF NOT EXISTS model_jobs_pending ON model_jobs(status,created_at);
CREATE TABLE IF NOT EXISTS summaries(conversation_id TEXT PRIMARY KEY REFERENCES conversations(id),owner_id TEXT NOT NULL,revision INTEGER NOT NULL,content TEXT,source_json TEXT NOT NULL,context_epoch INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS derivations(record_id TEXT NOT NULL REFERENCES records(id),source_type TEXT NOT NULL,source_id TEXT NOT NULL,source_revision INTEGER NOT NULL,PRIMARY KEY(record_id,source_type,source_id));
CREATE TABLE IF NOT EXISTS trigger_rules(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,revision INTEGER NOT NULL,enabled INTEGER NOT NULL,rule_json TEXT NOT NULL,action_json TEXT NOT NULL,next_at INTEGER,last_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS trigger_firings(id TEXT PRIMARY KEY,trigger_id TEXT NOT NULL REFERENCES trigger_rules(id),scheduled_at INTEGER NOT NULL,status TEXT NOT NULL,result TEXT,job_id TEXT,created_at INTEGER NOT NULL,UNIQUE(trigger_id,scheduled_at));
CREATE TABLE IF NOT EXISTS rest_cycles(id TEXT PRIMARY KEY,phase TEXT NOT NULL,revision INTEGER NOT NULL,started_at INTEGER NOT NULL,wake_at INTEGER NOT NULL,drain_until INTEGER NOT NULL,completed_at INTEGER,source_key TEXT NOT NULL,result TEXT);
CREATE TABLE IF NOT EXISTS feature_policies(name TEXT PRIMARY KEY,revision INTEGER NOT NULL,value_json TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS media_assets(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,conversation_id TEXT NOT NULL,kind TEXT NOT NULL,mime TEXT NOT NULL,digest TEXT NOT NULL,bytes BLOB NOT NULL,created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS run_media(run_id TEXT PRIMARY KEY REFERENCES runs(id),asset_id TEXT NOT NULL REFERENCES media_assets(id),description TEXT,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plugin_versions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,revision INTEGER NOT NULL,manifest_json TEXT NOT NULL,source TEXT NOT NULL,digest TEXT NOT NULL,status TEXT NOT NULL,test_json TEXT,approved_digest TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS relationship_proposals(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,job_id TEXT NOT NULL,source_json TEXT NOT NULL,payload TEXT,status TEXT NOT NULL,revision INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS automatic_runs(run_id TEXT PRIMARY KEY REFERENCES runs(id),kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rest_requests(request_id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,result_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS context_selections(run_id TEXT PRIMARY KEY REFERENCES runs(id),owner_id TEXT NOT NULL,details_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS local_runs(run_id TEXT PRIMARY KEY REFERENCES runs(id),kind TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS firing_snapshots(firing_id TEXT PRIMARY KEY REFERENCES trigger_firings(id),trigger_revision INTEGER NOT NULL,action_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_annotations(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),owner_id TEXT NOT NULL,kind TEXT NOT NULL,revision INTEGER NOT NULL,content TEXT,expires_at INTEGER,context_epoch INTEGER NOT NULL,status TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS operator_calls(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,operation_id TEXT NOT NULL,fingerprint TEXT NOT NULL,outcome TEXT NOT NULL,result_json TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS affinity_events(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,person_id TEXT NOT NULL REFERENCES records(id),delta REAL NOT NULL,reason TEXT,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS person_aliases(alias_id TEXT PRIMARY KEY,person_id TEXT NOT NULL REFERENCES records(id),owner_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS run_publications(run_id TEXT PRIMARY KEY REFERENCES runs(id),state TEXT NOT NULL,reason TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS prompt_snapshots(run_id TEXT PRIMARY KEY REFERENCES runs(id),owner_id TEXT NOT NULL,context_epoch INTEGER NOT NULL,messages_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS prompt_snapshot_expiry ON prompt_snapshots(created_at);
CREATE INDEX IF NOT EXISTS audit_filters ON audit_events(owner_id,kind,status,id);
CREATE INDEX IF NOT EXISTS audit_expiry ON audit_events(created_at);
CREATE TRIGGER IF NOT EXISTS journal_messages AFTER INSERT ON messages BEGIN INSERT INTO audit_events(owner_id,kind,status,title,resource_id,created_at) SELECT r.owner_id,CASE new.role WHEN 'user' THEN 'input' ELSE 'output' END,'recorded',CASE new.role WHEN 'user' THEN '收到消息' ELSE '生成候选' END,new.id,new.created_at FROM runs r WHERE r.id=new.run_id; END;
CREATE TRIGGER IF NOT EXISTS journal_run_status AFTER UPDATE OF status ON runs WHEN old.status<>new.status BEGIN INSERT INTO audit_events(owner_id,kind,status,title,resource_id,created_at) VALUES(new.owner_id,'run',new.status,CASE new.status WHEN 'running' THEN '正在生成回复' WHEN 'completed' THEN '回复已生成并保存' WHEN 'cancelled' THEN '运行已取消' WHEN 'failed' THEN '运行失败' WHEN 'interrupted' THEN '运行已中断' ELSE '运行状态已更新' END,new.id,CAST(strftime('%s','now') AS INTEGER)); END;
CREATE TRIGGER IF NOT EXISTS journal_retention AFTER INSERT ON audit_events BEGIN DELETE FROM audit_events WHERE id<=new.id-20000 OR created_at<CAST(strftime('%s','now') AS INTEGER)-2592000; DELETE FROM prompt_snapshots WHERE created_at<CAST(strftime('%s','now') AS INTEGER)-2592000; END;
CREATE TRIGGER IF NOT EXISTS journal_context_removed AFTER DELETE ON audit_events WHEN old.kind='context' BEGIN DELETE FROM prompt_snapshots WHERE run_id=old.resource_id; END;
INSERT INTO record_fts(record_fts,rank) VALUES('secure-delete',1);
